import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyClaimDetailsStyles } from './index.style'

export const PolicyClaimDetails = (props) => {
  const {
    claimNumber, policyNumber, category, insuranceProvider, createdAt,
    packageCode, userName
  } = props.details
  const renderVerticalKeyValue = (key, value, keyAlign = 'left', className = '') => {
    return (
      <div className={className}>
        <CustomText
          size='10px'
          weight={600}
          color={AgentColorPallette.fontDarkerGrey}
          textAlign={keyAlign}
        >
          {key}
        </CustomText>
        <CustomText
          size='13px'
          weight={800}
          color={AgentColorPallette.regular}
          textAlign={keyAlign}
        >
          {value}
        </CustomText>
      </div>
    )
  }
  return (
    <PolicyClaimDetailsStyles>
      <Row align='center' className='claim-type'>
        <CustomText
          size='0.5em'
          weight={500}
          color={AgentColorPallette.fontGrey}
          bottom='0'
        >
          {insuranceProvider}
        </CustomText>
      </Row>
      <Row align='center' className='claim-type'>
        <CustomText
          size='1.25em'
          weight={800}
          color={AgentColorPallette.black}
          bottom='0'
        >
          {packageCode}
        </CustomText>
      </Row>
      <Row align='center' justify='space-between' className='claim-number'>
        <CustomText
          size='0.75em'
          weight={700}
          color={AgentColorPallette.white}
          bottom='0'
        >
          {LANG_STRINGS.claimNumber}
        </CustomText>
        <CustomText
          size='0.75em'
          weight={700}
          color={AgentColorPallette.white}
          bottom='0'
        >
          {claimNumber}
        </CustomText>
      </Row>
      <Row justify='space-between' className='claim-type'>
        {renderVerticalKeyValue('CLAIM STARTED', createdAt?.split(' ')[0])}
        {renderVerticalKeyValue('INSURED NAME', userName, 'right')}
      </Row>
      <Row justify='space-between' className='claim-type'>
        {renderVerticalKeyValue('POLICY NUMBER', policyNumber)}
        {renderVerticalKeyValue('INSURANCE CATEGORY', category, 'right')}
      </Row>
    </PolicyClaimDetailsStyles>
  )
}
