import { CustomCollapse } from '../../../../../components'
import { ToggleStyleWrapper } from './index.style'
import QuoteSection from '../../../../Private/Policy/pages/MVQuoteReview/components/QuoteSections'
import { useMemo } from 'react'
import { isArray } from 'lodash'

export const ToggleComponent = ({ title, options }) => {
  const document = useMemo(() => {
    return options.reduce((acc, attribute) => {
      let { label: title, value, type } = attribute
      let multiImagePayload = {}

      if (type === 'image') {
        if (isArray(value)) { // to handle multiple image uploads
          value = value.reduce((imageArray, img, index) => {
            return [...imageArray, { url: img, fileName: `${title}_${index}` }]
          }, [])
          multiImagePayload = {
            isMultiple: true,
            value
          }
        }
        type = 'img'
      }
      return [...acc, { title, value, type, ...multiImagePayload }]
    }, [])
  }, [options])

  return (
    <ToggleStyleWrapper>
      <CustomCollapse hideBorders headingClass='heading' label={title} isOpened={false}>
        <QuoteSection
          data={document}
        />
      </CustomCollapse>
    </ToggleStyleWrapper>
  )
}
