import { ConfigUrl } from '../../../../configs/url'

export const POLICYCLAIM_ACTIONS = {
  GET_CLAIM_DETAILS: 'GET_CLAIM_DETAILS'
}

export const getCliamDetails = (payload) => {
  return {
    type: POLICYCLAIM_ACTIONS.GET_CLAIM_DETAILS,
    payload: {
      url: ConfigUrl.claimDetailsApi(payload.claimId),
      method: 'GET'
    }
  }
}
