import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

export const PolicyClaimContext = createContext()

export const PolicyClaimContextProvider = ({ children, ...props }) => {
  return (
    <PolicyClaimContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {children}
    </PolicyClaimContext.Provider>
  )
}

export const usePolicyClaimContextValue = () => useContext(PolicyClaimContext)
