import { POLICYCLAIM_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case POLICYCLAIM_ACTIONS.GET_CLAIM_DETAILS:
      return {
        ...state,
        getClaimDetailsData: { ...state.getClaimDetailsData, ...(payload.getClaimDetailsData || {}) }
      }
    default:
      return state
  }
}
export default reducer
