import { ConfigUrl } from '../../../../../../configs/url'

export const GIVE_FEEDBACK_ACTIONS = {
  GET_GIVE_FEEDBACK_FORM: 'GET_GIVE_FEEDBACK_FORM',
  SUBMIT_GIVE_FEEDBACK_FORM: 'SUBMIT_GIVE_FEEDBACK_FORM',
  RESET_GIVE_FEEDBACK_FORM: 'RESET_GIVE_FEEDBACK_FORM'
}

export const getGiveFeedbackForm = (payload) => {
  return {
    type: GIVE_FEEDBACK_ACTIONS.GET_GIVE_FEEDBACK_FORM,
    payload: {
      url: ConfigUrl.giveFeedbackFormApi(payload.feedback_request_id, payload.rating),
      method: 'GET'
    }
  }
}

export const submitGiveFeedbackForm = (payload) => {
  return {
    type: GIVE_FEEDBACK_ACTIONS.SUBMIT_GIVE_FEEDBACK_FORM,
    payload: {
      ...payload,
      url: ConfigUrl.submitGiveFeedbackFormApi(payload.feedback_request_id),
      method: 'POST'
    }
  }
}

export const resetGiveFeedbackForm = () => {
  return {
    type: GIVE_FEEDBACK_ACTIONS.RESET_GIVE_FEEDBACK_FORM
  }
}
