import { useCallback } from 'react'
import { ReactComponent as Star } from '../../../../../images/star.svg'
import { StarRatingsStyle } from './index.style'

const StarRatings = props => {
  const { totalRating = 5, currentRating = 0, onChangeRating = () => {}, leftText = 'VERY BAD', rightText = 'VERY GOOD', canBeZero = false } = props
  const handleChangeRating = useCallback((i) => {
    if (currentRating === i + 1) {
      if (canBeZero) onChangeRating(0)
    } else onChangeRating(i + 1)
  }, [canBeZero, currentRating, onChangeRating])
  return (
    <StarRatingsStyle>
      <div className='rating-container'>
        <div className='left-text'>{leftText}</div>
        <div className='star-container'>
          {
            Array(totalRating).fill(1).map((x, i) => {
              return <Star className={`star${i < currentRating ? ' star-filled' : ' star-empty'}`} key={i} onClick={() => handleChangeRating(i)} />
            })
          }
        </div>
        <div className='right-text'>{rightText}</div>
      </div>
    </StarRatingsStyle>
  )
}

export default StarRatings
