import { useCallback } from 'react'
import { ChipSectionStyles } from './index.style'

const ChipSection = (props) => {
  const { options = [], currentValues = [], handleChange } = props
  const handleOnChange = useCallback((name) => {
    const index = currentValues.indexOf(name)
    if (index >= 0) {
      const newCurrentValues = [...currentValues.slice(0, index), ...currentValues.slice(index + 1)]
      handleChange(newCurrentValues)
    } else {
      handleChange([...currentValues, name])
    }
  }, [currentValues, handleChange])

  return (
    <ChipSectionStyles>
      {options.map((option) => {
        return (
          <div
            key={option.name}
            onClick={() => handleOnChange(option.name)}
            className={`chip${currentValues.includes(option.name) ? ' selected' : ''}`}
          >
            {option.label}
          </div>)
      })}
    </ChipSectionStyles>
  )
}

export default ChipSection
