import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { ClaimStatusBar } from '../ClaimStatusBar'
import { ClaimStatusStyle } from './index.style'

export const ClaimStatus = ({ steps, status }) => {
  let activeItem = steps?.filter((item) => item.active)
  if (activeItem) {
    activeItem = activeItem[activeItem.length - 1]
  }

  return (
    <ClaimStatusStyle>
      <Row align='center' justify='center' className='claim-status-progress-bar'>
        <ClaimStatusBar steps={steps} />
      </Row>
      <Row align='center' bgColor={activeItem?.color} className='claim-status-box'>
        <CustomText
          size='0.75em'
          weight={500}
          color={AgentColorPallette.blackGrey}
          bottom='0'
        >
          <span className='claim-complete'>{activeItem?.title}</span>{'  '}
          {status?.display_message}
        </CustomText>
      </Row>
    </ClaimStatusStyle>
  )
}
