import { AgentColorPallette } from '../configs/colorPallete'

function claimStatesManager (key, isActive, activePositionIcon, color) {
  const claimStatesGroups = {
    claim_started: {
      title: 'KLAIM DIMULAI',
      color,
      active: isActive,
      activePositionIcon
    },
    document_pending: {
      title: 'DOKUMEN TERTUNDA',
      color,
      active: isActive,
      activePositionIcon
    },
    document_verification: {
      title: 'VERIFIKASI DOKUMEN',
      color,
      active: isActive,
      activePositionIcon
    },
    document_received: {
      title: 'DOKUMEN DITERIMA',
      color,
      active: isActive,
      activePositionIcon
    },
    document_complete: {
      title: 'DOKUMEN LENGKAP',
      color,
      active: isActive,
      activePositionIcon
    },
    document_reprocess: {
      title: 'REPROSES DOKUMEN',
      color,
      active: isActive,
      activePositionIcon
    },
    on_survey: {
      title: 'DI SURVEI',
      color,
      active: isActive,
      activePositionIcon
    },
    workjob_complete: {
      title: 'PEKERJAAN SELESAI',
      color,
      active: isActive,
      activePositionIcon
    },
    claim_complete: {
      title: 'KLAIM SELESAI',
      color,
      active: isActive,
      activePositionIcon
    },
    claim_denied: {
      title: 'KLAIM DITOLAK',
      color,
      active: isActive,
      activePositionIcon
    },
    claim_closed: {
      title: 'KLAIM DITUTUP',
      color,
      active: isActive,
      activePositionIcon
    }
  }
  return claimStatesGroups[key]
}

