import { Container } from '../../../../components'
import { LANG_STRINGS } from '../../../../lang'
import { PolicyClaimStyle } from './index.style'
import { ClaimStatus } from '../components/ClaimStatus/index.js'
import { PolicyClaimDetails } from '../components/PolicyClaimDetails'
import { ToggleComponent } from '../components/ToggleComponent'
import { useEffect, useRef } from 'react'
import { useGetClaimDetails } from '../state/hooks/usePolicyClaim'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { claimStates } from '../../../../helpers/claimUtils'
import { useParams } from 'react-router'
import size from 'lodash/size'
import GiveFeedback from '../components/GiveFeedback'
import get from 'lodash/get'

const PolicyClaim = (props) => {
  const { claimId } = useParams()
  const [{ getClaimDetailsData = {} }, getClaimDetailsRequest] = useGetClaimDetails()
  const [{ GET_CLAIM_DETAILS_LOADER }] = useLoaderContextValue()
  const [{ getClaimDetailsStatus }] = useErrorContextValue()

  const that = useRef({
    claimDetails: {}
  })

  useEffect(() => {
    getClaimDetailsRequest({ claimId })
  }, [getClaimDetailsRequest, claimId])

  useEffect(() => {
    if (getClaimDetailsStatus === 'success' && size(getClaimDetailsData)) {
      const {
        claim_no: claimNumber, policy_number: policyNumber, category,
        insurance_provider: insuranceProvider, created_at: createdAt,
        package_code: packageCode, user_name: userName
      } = getClaimDetailsData

      that.current.claimDetails = {
        claimNumber,
        policyNumber,
        category,
        insuranceProvider,
        createdAt,
        packageCode,
        userName
      }
    }
  }, [getClaimDetailsData, getClaimDetailsStatus])

  return (
    <Container
      title={LANG_STRINGS.claimStatus}
      hideBottomTabs
      className='claim-page'
      loader={GET_CLAIM_DETAILS_LOADER}
    >
      <PolicyClaimStyle>
        <ClaimStatus steps={claimStates[getClaimDetailsData?.status?.status_code]} status={getClaimDetailsData.status} />
        <PolicyClaimDetails details={that.current.claimDetails} />
        {
          getClaimDetailsData?.forms?.map((item, index) =>
            <ToggleComponent
              key={index}
              title={item.title}
              options={item.attributes}
            />
          )
        }
        {
          ['settled', 'claim_rejected'].includes(getClaimDetailsData?.status?.status_code) &&
          process.env.REACT_APP_SHOW_CLAIM_FEEDBACK === 'true' &&
            <GiveFeedback
              feedbackDetails={get(getClaimDetailsData, 'feedback_details', {})}
              onHandleReturn={() => getClaimDetailsRequest({ claimId })}
            />
        }
      </PolicyClaimStyle>
    </Container>
  )
}
export default PolicyClaim
