import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { usePolicyClaimContextValue } from '../../context'
import {
  getCliamDetails
} from '../actions'

export const usePolicyClaimServiceCall = (actionsCall = () => {}) => {
  const [policyClaimState, dispatch] = usePolicyClaimContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [actionsCall, callApi])

  return [policyClaimState, request]
}

export const useGetClaimDetails = () => usePolicyClaimServiceCall(getCliamDetails)
