import { GIVE_FEEDBACK_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case GIVE_FEEDBACK_ACTIONS.GET_GIVE_FEEDBACK_FORM:
      return {
        ...state,
        getGiveFeedbackFormData: { ...state.getGiveFeedbackFormData, ...(payload.getGiveFeedbackFormData || {}) }
      }
    case GIVE_FEEDBACK_ACTIONS.SUBMIT_GIVE_FEEDBACK_FORM:
      return {
        ...state,
        submitGiveFeedbackFormData: payload.submitGiveFeedbackFormData || ''
      }
    case GIVE_FEEDBACK_ACTIONS.RESET_GIVE_FEEDBACK_FORM:
      return INITIAL_STATE
    default:
      return state
  }
}
export default reducer
