import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

export const GiveFeedbackContext = createContext()

export const GiveFeedbackContextProvider = ({ children, ...props }) => {
  return (
    <GiveFeedbackContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {children}
    </GiveFeedbackContext.Provider>
  )
}

export const useGiveFeedbackContextValue = () => useContext(GiveFeedbackContext)
