import { useEffect, useMemo, useState } from 'react'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Button } from '../../../../../components'
import { GiveFeedbackStyle, GiveFeedBackModalStyle, MarginFixStyle } from './index.style'
import StarRatings from '../StarRatings'
import Textarea from '../../../../../components/Textarea'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import ChipSection from '../ChipSection'
import { LANG_STRINGS } from '../../../../../lang'
import { useGiveFeedbackForm, useResetGiveFeedBackForm, useSubmitGiveFeedbackForm } from './state/hooks/useGiveFeedbackForm'
import { GiveFeedbackContextProvider } from './context'
import CircularLoader from '../../../../../components/CircularLoader'
import { INFORMATION_SENT } from '../../../../../images'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

const GiveFeedback = props => {
  const { feedbackDetails, onHandleReturn } = props
  const [{ getGiveFeedbackFormData = {} }, getGiveFeedbackFormRequest] = useGiveFeedbackForm()
  const [{ submitGiveFeedbackFormData = '' }, submitGiveFeedbackFormRequest] = useSubmitGiveFeedbackForm()
  const [, resetGiveFeedbackFormRequest] = useResetGiveFeedBackForm()
  const [{ GET_GIVE_FEEDBACK_FORM_LOADER, SUBMIT_GIVE_FEEDBACK_FORM_LOADER }] = useLoaderContextValue()
  const [open, setOpen] = useState(false)
  const [currentRating, setCurrentRating] = useState(0)
  const [selected, setSelected] = useState([])
  const [suggestion, setSuggestion] = useState('')
  const isDisabled = useMemo(() => {
    if (currentRating < 1) return true
    if (getGiveFeedbackFormData?.is_required_title && selected.length < 1) return true
    if (getGiveFeedbackFormData?.is_required_label && suggestion.length < 1) return true
    if (GET_GIVE_FEEDBACK_FORM_LOADER) return true
    return false
  }, [currentRating, getGiveFeedbackFormData, selected, suggestion, GET_GIVE_FEEDBACK_FORM_LOADER])
  const handleClose = () => {
    setCurrentRating(0)
    setSelected([])
    setSuggestion('')
    setOpen(false)
  }
  const handleSendFeedback = () => {
    submitGiveFeedbackFormRequest({
      feedback_request_id: feedbackDetails?.feedback_request_id,
      body: {
        feedback_request_id: feedbackDetails?.feedback_request_id,
        rating: currentRating,
        review: suggestion,
        source: 'direct',
        submitted_options: [...selected]
      }
    })
  }
  const handleReturn = () => {
    setOpen(false)
    resetGiveFeedbackFormRequest()
    onHandleReturn()
  }
  useEffect(() => {
    if (feedbackDetails.is_rated) return
    getGiveFeedbackFormRequest(
      {
        feedback_request_id: feedbackDetails?.feedback_request_id,
        rating: currentRating
      })
    setSelected([])
  }, [feedbackDetails, currentRating, getGiveFeedbackFormRequest])

  return !feedbackDetails?.is_rated && (
    <>
      <div style={{ paddingBottom: '82px' }} />
      <MarginFixStyle>
        <GiveFeedbackStyle>
          <Button
            handleClick={() => setOpen(true)}
            padTop='16px'
            padBtm='16px'
          >
            {LANG_STRINGS.giveFeedback}
          </Button>
          <GiveFeedBackModalStyle>
            <BottomActionSheet
              show={open}
              onCloseSheet={
                SUBMIT_GIVE_FEEDBACK_FORM_LOADER
                  ? () => {}
                  : submitGiveFeedbackFormData === 'Success'
                    ? handleReturn
                    : handleClose
              }
              showHeader
              title={LANG_STRINGS.giveFeedback}
            >
              <div className={submitGiveFeedbackFormData !== 'Success' ? 'modal-container' : ''}>
                <div className='modal-content'>
                  {submitGiveFeedbackFormData === 'Success' ? (
                    <>
                      <div className='thank-you'>
                        <img src={INFORMATION_SENT} alt='feedback Submitted Successfully' />
                        <h2>{LANG_STRINGS.thankYou}</h2>
                        {LANG_STRINGS.feedbackThanksNote}
                      </div>
                      <br />
                      <br />
                      <Button
                        handleClick={handleReturn}
                        padTop='16px' padBtm='16px'
                      >
                        {LANG_STRINGS.return}
                      </Button>
                    </>
                  ) : (
                    <CircularLoader isLoading={SUBMIT_GIVE_FEEDBACK_FORM_LOADER}>
                      <div className='section-title'>{LANG_STRINGS.satisfied}</div>
                      <StarRatings
                        leftText={LANG_STRINGS.feedbackLowest}
                        rightText={LANG_STRINGS.feedbackHighest}
                        totalRating={5}
                        currentRating={currentRating}
                        onChangeRating={(x) => setCurrentRating(x)}
                      />
                      <hr />
                      <CircularLoader
                        isLoading={GET_GIVE_FEEDBACK_FORM_LOADER}
                        bgColor={AgentColorPallette.transparent}
                      >
                        <div className='section-title'>{getGiveFeedbackFormData?.title || ''}</div>
                        <ChipSection
                          options={getGiveFeedbackFormData?.options || []}
                          currentValues={selected}
                          handleChange={(values) => setSelected(values)}
                        />
                        <hr />
                      </CircularLoader>
                      <div className='section-title'>{getGiveFeedbackFormData?.label || ''}</div>
                      <Textarea
                        onChange={(e) => setSuggestion(e.target.value)}
                        value={suggestion} displayBorder placeholder=' '
                        resize='vertical'
                        name='suggestion'
                        className='suggestion'
                        rows={5}
                      />
                      <br />
                    </CircularLoader>
                  )}
                  {submitGiveFeedbackFormData !== 'Success' &&
                    (
                      <>
                        <div className='send-feedback-padding'> </div>
                        <div className='send-feedback'>
                          <Button
                            disabled={isDisabled}
                            handleClick={handleSendFeedback}
                            padTop='16px' padBtm='16px'
                          >
                            {LANG_STRINGS.send}
                          </Button>
                        </div>
                      </>
                    )}
                </div>
              </div>
            </BottomActionSheet>
          </GiveFeedBackModalStyle>
        </GiveFeedbackStyle>
      </MarginFixStyle>
    </>
  )
}

const GiveFeedbackWC = (props) => (
  <GiveFeedbackContextProvider>
    <GiveFeedback {...props} />
  </GiveFeedbackContextProvider>)
export default GiveFeedbackWC
