import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useGiveFeedbackContextValue } from '../../context'
import {
  getGiveFeedbackForm, submitGiveFeedbackForm, resetGiveFeedbackForm
} from '../actions'

export const useGiveFeedbackServiceCall = (actionsCall = () => {}) => {
  const [giveFeedbackFormState, dispatch] = useGiveFeedbackContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [actionsCall, callApi])

  return [giveFeedbackFormState, request]
}

export const useGiveFeedbackForm = () => useGiveFeedbackServiceCall(getGiveFeedbackForm)
export const useSubmitGiveFeedbackForm = () => useGiveFeedbackServiceCall(submitGiveFeedbackForm)
export const useResetGiveFeedBackForm = () => {
  const [giveFeedbackFormState, dispatch] = useGiveFeedbackContextValue()
  return [giveFeedbackFormState, () => dispatch(resetGiveFeedbackForm())]
}
