import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { ClaimStatusBarStyle } from './index.style'

export const ClaimStatusBar = ({ steps }) => {
  const getActiveClass = (iconType) => {
    switch (iconType) {
      case 'fa-check': return 'active'
      case 'fa-times': return 'rejected'
      case 'fa-sync-alt': return 'pending'
      default: return 'default'
    }
  }

  return (
    <ClaimStatusBarStyle>
      <ul className='timeline'>
        {
          steps?.map && steps.map((item, index) => (
            <li key={index} className={`steps-list ${getActiveClass(item.activePositionIcon)}`}>
              <div className={`step ${getActiveClass(item.activePositionIcon)}`}>
                <i className={`fas ${item.activePositionIcon}`} />
              </div>
              <CustomText
                size='8px'
                weight={800}
                color={AgentColorPallette.black}
                textAlign='center'
              >
                {item.title}
              </CustomText>
            </li>
          ))
        }
      </ul>
    </ClaimStatusBarStyle>
  )
}
